package org.eclipse.jdt.internal.ui.dialogs;

import java.util.Arrays;
import org.eclipse.ui.IWorkingSet;
import org.eclipse.ui.IWorkingSetManager;
import org.eclipse.core.runtime.IAdaptable;

public class TestClass {
    void createOrUpdateWorkingSet(String name, String oldname, String label, final String id, IWorkingSetManager workingSetManager) {
        // This is the target line
        IWorkingSet workingSet = Arrays.stream(workingSetManager.getAllWorkingSets())
                .filter(w -> id.equals(w.getId()) && name.equals(w.getName()))
                .findAny()
                .orElse(null);
        System.out.println(workingSet);
    }
}

