package org.eclipse.jdt.internal.ui.dialogs;

import java.util.Arrays;
import org.eclipse.ui.IWorkingSet;
import org.eclipse.ui.IWorkingSetManager;
import org.eclipse.core.runtime.IAdaptable;

public class NegativeTestClass {
    void findWorkingSetByLabel(String labelToFind, IWorkingSetManager workingSetManager) {
        // This stream operation has a different filter condition, should not be matched.
        IWorkingSet foundSet = Arrays.stream(workingSetManager.getAllWorkingSets())
                .filter(ws -> labelToFind.equals(ws.getLabel()))
                .findAny()
                .orElse(null);
        System.out.println(foundSet);

        // This uses getWorkingSet directly, which is not the pattern.
        IWorkingSet directLookup = workingSetManager.getWorkingSet("someName");
        System.out.println(directLookup);
    }
}
